import pandas as pd

def find_largest_difference_location(data):
    # Calculate the difference between the 99th and 1st percentile of the z-axis acceleration
    data['z_diff'] = data['accel_stats_z_p99'] - data['accel_stats_z_p1']

    # Find the location with the largest difference
    max_diff_location = data.loc[data['z_diff'].idxmax()]

    # Validate the reported location
    if -90 <= max_diff_location['latitude'] <= 90 and -180 <= max_diff_location['longitude'] <= 180:
        # Format the reported result using Pandas
        result = pd.DataFrame({
            'latitude': [max_diff_location['latitude']],
            'longitude': [max_diff_location['longitude']]
        })
        return result
    else:
        return None

